#include <WiFi.h>
#include <WebServer.h>

const char* WIFI_SSID = "DIR-615T-0DBC";
const char* WIFI_PASS = "23233010";

// HTML прямо в коде, лежит во флеше и RAM не тратит
const char INDEX_HTML[] PROGMEM = R"html(
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>ESP32</title>
  <style>
    body { font-family: sans-serif; display: flex; justify-content: center;
           align-items: center; height: 100vh; margin: 0; }
    h1 { color: #2c7; }
  </style>
</head>
<body>
  <h1>Привет с ESP32!</h1>
</body>
</html>
)html";

WebServer server(80);

void setup() {
  Serial.begin(115200);

  WiFi.begin(WIFI_SSID, WIFI_PASS);
  while (WiFi.status() != WL_CONNECTED) {
    delay(300);
    Serial.print(".");
  }
  Serial.print("\nIP: ");
  Serial.println(WiFi.localIP());

  // любой запрос отдаёт страницу
  server.onNotFound([]() {
    server.send_P(200, "text/html", INDEX_HTML);
  });

  server.begin();
}

void loop() {
  server.handleClient();
}
